ALTER TABLE public.org_subscription_options ADD COLUMN IF NOT EXISTS white_label_enabled boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS trial_white_label_enabled boolean NOT NULL DEFAULT false;
DROP FUNCTION IF EXISTS app_private.org_effective_options(uuid);
CREATE FUNCTION app_private.org_effective_options(_firm_id uuid) RETURNS TABLE(advisory boolean, consolidation boolean, branding boolean, white_label boolean, purchased_advisory boolean, purchased_consolidation boolean, purchased_branding boolean, purchased_white_label boolean, trial_advisory boolean, trial_consolidation boolean, trial_branding boolean, trial_white_label boolean, trial_ends_at timestamptz, trial_active boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ WITH o AS (SELECT coalesce(opt.advisory_enabled,false) p_adv,coalesce(opt.consolidation_enabled,false) p_con,coalesce(opt.branding_enabled,false) p_brand,coalesce(opt.white_label_enabled,false) p_white,coalesce(opt.trial_advisory_enabled,false) t_adv,coalesce(opt.trial_consolidation_enabled,false) t_con,coalesce(opt.trial_branding_enabled,false) t_brand,coalesce(opt.trial_white_label_enabled,false) t_white,opt.trial_ends_at t_end FROM public.org_subscription_options opt WHERE opt.firm_id=_firm_id),r AS (SELECT coalesce((SELECT p_adv FROM o),false) p_adv,coalesce((SELECT p_con FROM o),false) p_con,coalesce((SELECT p_brand FROM o),false) p_brand,coalesce((SELECT p_white FROM o),false) p_white,coalesce((SELECT t_adv FROM o),false) t_adv,coalesce((SELECT t_con FROM o),false) t_con,coalesce((SELECT t_brand FROM o),false) t_brand,coalesce((SELECT t_white FROM o),false) t_white,(SELECT t_end FROM o) t_end),live AS (SELECT r.*,(r.t_end IS NOT NULL AND r.t_end>now()) t_live FROM r) SELECT (p_adv OR (t_live AND t_adv)),(p_con OR (t_live AND t_con)) AND (p_adv OR (t_live AND t_adv)),(p_brand OR (t_live AND t_brand)) AND (p_adv OR (t_live AND t_adv)),(p_white OR (t_live AND t_white)),p_adv,p_con,p_brand,p_white,t_adv,t_con,t_brand,t_white,t_end,t_live FROM live $function$;
REVOKE ALL ON FUNCTION app_private.org_effective_options(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION app_private.org_effective_options(uuid) TO service_role;
CREATE OR REPLACE FUNCTION app_private.firm_white_label_enabled(_firm_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT coalesce((SELECT e.white_label FROM app_private.org_effective_options(_firm_id) e),false) AND NOT app_private.firm_subscription_lapsed(_firm_id) $function$;
REVOKE ALL ON FUNCTION app_private.firm_white_label_enabled(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION app_private.firm_white_label_enabled(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.workspace_branding_for_firm(_firm_id uuid) RETURNS TABLE(firm_id uuid,organisation_name text,logo_path text,white_label_enabled boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN PERFORM app_private.assert_aal2(); IF auth.uid() IS NULL OR NOT app_private.has_firm_access(auth.uid(),_firm_id) THEN RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege'; END IF; RETURN QUERY SELECT f.id,f.name,CASE WHEN app_private.firm_white_label_enabled(f.id) THEN f.logo_path ELSE NULL END,app_private.firm_white_label_enabled(f.id) FROM public.firms f WHERE f.id=_firm_id; END $function$;
REVOKE ALL ON FUNCTION public.workspace_branding_for_firm(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workspace_branding_for_firm(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.workspace_branding_for_client(_client_id uuid) RETURNS TABLE(firm_id uuid,organisation_name text,logo_path text,white_label_enabled boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE _firm_id uuid; BEGIN PERFORM app_private.assert_aal2(); IF auth.uid() IS NULL OR NOT app_private.user_can_read_client(auth.uid(),_client_id) THEN RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege'; END IF; SELECT c.firm_id INTO _firm_id FROM public.clients c WHERE c.id=_client_id; RETURN QUERY SELECT f.id,f.name,CASE WHEN app_private.firm_white_label_enabled(f.id) THEN f.logo_path ELSE NULL END,app_private.firm_white_label_enabled(f.id) FROM public.firms f WHERE f.id=_firm_id; END $function$;
REVOKE ALL ON FUNCTION public.workspace_branding_for_client(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workspace_branding_for_client(uuid) TO authenticated,service_role;
DROP FUNCTION IF EXISTS public.org_purchase(uuid);
CREATE FUNCTION public.org_purchase(_firm_id uuid) RETURNS TABLE(firm_id uuid,client_limit integer,advisory_enabled boolean,consolidation_enabled boolean,branding_enabled boolean,white_label_enabled boolean,billing_mode text,client_count integer,trial_advisory_enabled boolean,trial_consolidation_enabled boolean,trial_branding_enabled boolean,trial_white_label_enabled boolean,trial_ends_at timestamptz,trial_active boolean,effective_advisory boolean,effective_consolidation boolean,effective_branding boolean,effective_white_label boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN PERFORM app_private.assert_aal2(); IF auth.uid() IS NULL OR (NOT public.user_can_access_firm(auth.uid(),_firm_id) AND NOT app_private.platform_staff_can_access_firm(auth.uid(),_firm_id) AND NOT app_private.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'NO_ACCESS' USING errcode='insufficient_privilege'; END IF; RETURN QUERY SELECT f.id,coalesce(o.client_limit,0),coalesce(o.advisory_enabled,false),coalesce(o.consolidation_enabled,false),coalesce(o.branding_enabled,false),coalesce(o.white_label_enabled,false),coalesce(o.billing_mode,'bookkeeping'),(SELECT count(*)::int FROM public.clients c WHERE c.firm_id=f.id),coalesce(o.trial_advisory_enabled,false),coalesce(o.trial_consolidation_enabled,false),coalesce(o.trial_branding_enabled,false),coalesce(o.trial_white_label_enabled,false),o.trial_ends_at,e.trial_active,e.advisory,e.consolidation,e.branding,e.white_label FROM public.firms f LEFT JOIN public.org_subscription_options o ON o.firm_id=f.id CROSS JOIN LATERAL app_private.org_effective_options(f.id) e WHERE f.id=_firm_id; END $function$;
REVOKE ALL ON FUNCTION public.org_purchase(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.org_purchase(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.set_org_purchase(_firm_id uuid,_client_limit integer,_advisory boolean,_consolidation boolean,_branding boolean,_white_label boolean,_billing_mode text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE _prev_advisory boolean:=false; _prev_consolidation boolean:=false; _siblings int; BEGIN PERFORM app_private.assert_aal2(); PERFORM public.assert_super_admin(); IF _billing_mode IS NULL OR _billing_mode NOT IN ('bookkeeping','external') THEN RAISE EXCEPTION 'INVALID_BILLING_MODE' USING errcode='check_violation'; END IF; IF _client_limit IS NULL OR _client_limit<0 OR _client_limit>9999 THEN RAISE EXCEPTION 'INVALID_CLIENT_LIMIT' USING errcode='check_violation'; END IF; IF coalesce(_consolidation,false) AND NOT coalesce(_advisory,false) THEN RAISE EXCEPTION 'CONSOLIDATION_REQUIRES_ADVISORY' USING errcode='check_violation'; END IF; IF coalesce(_branding,false) AND NOT coalesce(_advisory,false) THEN RAISE EXCEPTION 'BRANDING_REQUIRES_ADVISORY' USING errcode='check_violation'; END IF; IF NOT EXISTS(SELECT 1 FROM public.firms f WHERE f.id=_firm_id) THEN RAISE EXCEPTION 'NO_SUCH_ORGANISATION' USING errcode='no_data_found'; END IF; SELECT o.advisory_enabled,o.consolidation_enabled INTO _prev_advisory,_prev_consolidation FROM public.org_subscription_options o WHERE o.firm_id=_firm_id; INSERT INTO public.org_subscription_options(firm_id,client_limit,advisory_enabled,consolidation_enabled,branding_enabled,white_label_enabled,billing_mode) VALUES(_firm_id,_client_limit,coalesce(_advisory,false),coalesce(_consolidation,false),coalesce(_branding,false),coalesce(_white_label,false),_billing_mode) ON CONFLICT(firm_id) DO UPDATE SET client_limit=excluded.client_limit,advisory_enabled=excluded.advisory_enabled,consolidation_enabled=excluded.consolidation_enabled,branding_enabled=excluded.branding_enabled,white_label_enabled=excluded.white_label_enabled,billing_mode=excluded.billing_mode,updated_at=now(); IF coalesce(_advisory,false) AND NOT coalesce(_prev_advisory,false) THEN UPDATE public.client_cards cc SET cards=ARRAY(SELECT DISTINCT x FROM unnest(cc.cards||app_private.card_group_cards('advisory')) x ORDER BY x),updated_at=now() WHERE cc.client_id IN(SELECT c.id FROM public.clients c WHERE c.firm_id=_firm_id); END IF; SELECT count(*) INTO _siblings FROM public.clients c WHERE c.firm_id=_firm_id; IF coalesce(_consolidation,false) AND NOT coalesce(_prev_consolidation,false) AND _siblings>1 THEN UPDATE public.client_cards cc SET cards=ARRAY(SELECT DISTINCT x FROM unnest(cc.cards||app_private.card_group_cards('consolidation')) x ORDER BY x),updated_at=now() WHERE cc.client_id IN(SELECT c.id FROM public.clients c WHERE c.firm_id=_firm_id); END IF; INSERT INTO public.audit_log(actor_user_id,firm_id,action,target_type,target_id,meta) VALUES(auth.uid(),_firm_id,'org_purchase_set','firm',_firm_id::text,jsonb_build_object('client_limit',_client_limit,'advisory',coalesce(_advisory,false),'consolidation',coalesce(_consolidation,false),'branding',coalesce(_branding,false),'white_label',coalesce(_white_label,false),'billing_mode',_billing_mode)); END $function$;
REVOKE ALL ON FUNCTION public.set_org_purchase(uuid,integer,boolean,boolean,boolean,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_org_purchase(uuid,integer,boolean,boolean,boolean,boolean,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.set_org_trial(_firm_id uuid,_advisory boolean,_consolidation boolean,_branding boolean,_white_label boolean,_ends_at timestamptz,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE _ending boolean; BEGIN PERFORM app_private.assert_aal2(); PERFORM public.assert_super_admin(); _ending:=NOT coalesce(_advisory,false) AND NOT coalesce(_consolidation,false) AND NOT coalesce(_branding,false) AND NOT coalesce(_white_label,false); IF NOT _ending THEN IF _ends_at IS NULL OR _ends_at<=now() OR _ends_at>now()+interval '120 days' THEN RAISE EXCEPTION 'INVALID_TRIAL_END' USING errcode='check_violation'; END IF; IF coalesce(_consolidation,false) AND NOT coalesce(_advisory,false) THEN RAISE EXCEPTION 'CONSOLIDATION_REQUIRES_ADVISORY' USING errcode='check_violation'; END IF; IF coalesce(_branding,false) AND NOT coalesce(_advisory,false) THEN RAISE EXCEPTION 'BRANDING_REQUIRES_ADVISORY' USING errcode='check_violation'; END IF; IF nullif(btrim(_reason),'') IS NULL THEN RAISE EXCEPTION 'REASON_REQUIRED' USING errcode='check_violation'; END IF; END IF; INSERT INTO public.org_subscription_options(firm_id,trial_advisory_enabled,trial_consolidation_enabled,trial_branding_enabled,trial_white_label_enabled,trial_ends_at) VALUES(_firm_id,coalesce(_advisory,false),coalesce(_consolidation,false),coalesce(_branding,false),coalesce(_white_label,false),CASE WHEN _ending THEN NULL ELSE _ends_at END) ON CONFLICT(firm_id) DO UPDATE SET trial_advisory_enabled=excluded.trial_advisory_enabled,trial_consolidation_enabled=excluded.trial_consolidation_enabled,trial_branding_enabled=excluded.trial_branding_enabled,trial_white_label_enabled=excluded.trial_white_label_enabled,trial_ends_at=excluded.trial_ends_at,advisory_enabled=CASE WHEN coalesce(_advisory,false) THEN false ELSE org_subscription_options.advisory_enabled END,consolidation_enabled=CASE WHEN coalesce(_consolidation,false) THEN false ELSE org_subscription_options.consolidation_enabled END,branding_enabled=CASE WHEN coalesce(_branding,false) THEN false ELSE org_subscription_options.branding_enabled END,white_label_enabled=CASE WHEN coalesce(_white_label,false) THEN false ELSE org_subscription_options.white_label_enabled END,updated_at=now(); INSERT INTO public.audit_log(actor_user_id,firm_id,action,target_type,target_id,meta) VALUES(auth.uid(),_firm_id,CASE WHEN _ending THEN 'org_trial_ended' ELSE 'org_trial_set' END,'firm',_firm_id::text,jsonb_build_object('advisory',coalesce(_advisory,false),'consolidation',coalesce(_consolidation,false),'branding',coalesce(_branding,false),'white_label',coalesce(_white_label,false),'ends_at',CASE WHEN _ending THEN NULL ELSE _ends_at END,'reason',nullif(btrim(_reason),''))); END $function$;
REVOKE ALL ON FUNCTION public.set_org_trial(uuid,boolean,boolean,boolean,boolean,timestamptz,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_org_trial(uuid,boolean,boolean,boolean,boolean,timestamptz,text) TO authenticated,service_role;